import inspect, pandas as pd
print("pandas", pd.__version__)

print("\n=== TYPE 1: parameter that never existed (the classic AI invention) ===")
try: pd.read_csv("x.csv", auto_detect=True)
except TypeError as e: print(f"  pd.read_csv(path, auto_detect=True) -> TypeError: {e}")

print("\n=== TYPE 2: parameter removed across versions (was valid in older docs) ===")
for kw in [{"error_bad_lines": False}, {"squeeze": True}]:
    try:
        inspect.signature(pd.read_csv).bind("x.csv", **kw); print(f"  read_csv(**{kw}) still accepted")
    except TypeError as e: print(f"  pd.read_csv(path, **{kw}) -> {e}")

print("\n=== TYPE 3: method removed from the object entirely ===")
df = pd.DataFrame({"a": [1]})
for m in ["append", "iteritems", "ix"]:
    print(f"  df.{m}(...) -> {'exists' if hasattr(df, m) else 'AttributeError: no such method (removed in pandas 2.x)'}")

print("\n=== TYPE 4: wrong arity / positional order ===")
try: inspect.signature(pd.merge).bind()
except TypeError as e: print(f"  pd.merge() -> {e}")

print("\n=== TYPE 5: wrong return-type assumption (no exception at the call!) ===")
r = pd.DataFrame({"a":[1,2]}).iterrows()
print(f"  df.iterrows() returns {type(r).__name__}, NOT a list -> len() fails, len(list(r))={len(list(pd.DataFrame({'a':[1,2]}).iterrows()))}")
EOF
